        def _sync(self, obs, hist):
            i = hidx(obs["timestamp"])
            if i == self._cur:
                return i
            if self._cur is not None and (i < self._cur or (hist is not None and len(hist) == 1)):
                self.reset()                                   # a new run with the same instance
            nd = obs["noves_dades_5min"]
            last = float(nd["ultim_consum_kw"])
