            self._prev, self._cur, self._cache = prev, i, None
            if prev is not None:
                if last >= FAULT_KW:
                    self.tab[prev] = last                      # the reading belongs to the previous row
                else:
                    self.tab.pop(prev, None)
                tv = nd.get("temp_ambient_c")
